:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #233d35;
  background: #f4efe4;
  --ink: #233d35;
  --muted: #66786b;
  --paper: #fffdf7;
  --green: #477b61;
  --mint: #e8f0e6;
  --gold: #e3ae54;
  --line: #d9dfd2;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f4efe4;
  background-image: radial-gradient(#d8d1bd 1px, transparent 1px);
  background-size: 20px 20px;
}
button, input { font: inherit; }
.card {
  width: min(100%, 580px);
  padding: clamp(24px, 6vw, 48px);
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}
.header { text-align: center; }
.pixel-mark {
  width: 36px;
  height: 36px;
  margin: 0 auto 18px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 4px;
  transform: rotate(-5deg);
}
.pixel-mark span { background: var(--green); }
.pixel-mark span:nth-child(2), .pixel-mark span:nth-child(3) { background: var(--gold); }
.eyebrow, .result-label {
  margin: 0;
  color: var(--green);
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
h1 {
  margin: 8px 0 12px;
  font-size: clamp(2.25rem, 8vw, 3.25rem);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.intro { max-width: 34ch; margin: 0 auto 30px; color: var(--muted); line-height: 1.55; }
.fractions { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 14px; }
.fraction, .operations { min-width: 0; margin: 0; padding: 0; border: 0; }
.fraction legend, .operations legend {
  width: 100%;
  margin-bottom: 12px;
  color: var(--ink);
  font-size: 0.95rem;
  font-weight: 750;
  text-align: center;
}
.fraction label {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 650;
}
.fraction input {
  width: 100%;
  min-height: 48px;
  padding: 8px 12px;
  border: 2px solid var(--line);
  border-radius: 5px;
  outline: none;
  background: #fff;
  color: var(--ink);
  text-align: center;
  font-size: 1.2rem;
  font-weight: 700;
}
.fraction input:focus-visible { border-color: var(--green); box-shadow: 0 0 0 3px #477b6133; }
.fraction-line { height: 3px; margin: 8px 0; border-radius: 3px; background: var(--ink); }
.join { padding-top: 24px; color: var(--muted); font-size: 0.8rem; font-weight: 700; }
.operations { margin-top: 28px; }
.operations legend { margin-bottom: 10px; }
.operation-buttons { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.operation-buttons button {
  min-height: 56px;
  border: 2px solid var(--ink);
  border-radius: 5px;
  background: var(--mint);
  color: var(--ink);
  cursor: pointer;
  font-size: 1.7rem;
  font-weight: 700;
  transition: background-color 120ms ease, color 120ms ease, transform 120ms ease, box-shadow 120ms ease;
}
.operation-buttons button:hover { background: var(--green); color: white; }
.operation-buttons button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.operation-buttons button:active { transform: translateY(2px); box-shadow: inset 0 2px 0 #233d3540; }
.result {
  min-height: 132px;
  margin-top: 28px;
  padding: 20px;
  border: 2px dashed #a9b9a8;
  border-radius: 6px;
  background: #f6f8f0;
  text-align: center;
}
.result-label { color: var(--muted); }
.result-value { margin: 8px 0 2px; color: var(--ink); font-size: clamp(1.5rem, 6vw, 2.2rem); font-weight: 800; overflow-wrap: anywhere; }
.decimal-value { margin: 0; color: var(--green); font-size: 1rem; font-weight: 650; }
.error-message { margin: 6px 0 0; color: #a03d32; font-weight: 700; }
footer { margin-top: 24px; color: var(--muted); text-align: center; font-size: 0.85rem; }
footer span { color: var(--gold); }
@media (max-width: 420px) {
  body { padding: 20px 14px; }
  .card { box-shadow: 5px 5px 0 var(--ink); }
  .fractions { gap: 9px; }
  .join { font-size: 0.72rem; }
  .operation-buttons { gap: 7px; }
}

const calculator = document.querySelector("#calculator");
const resultValue = document.querySelector("#result-value");
const decimalValue = document.querySelector("#decimal-value");
const errorMessage = document.querySelector("#error-message");

function gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b) [a, b] = [b, a % b];
  return a || 1;
}

function readFraction(suffix) {
  const numerator = Number(document.querySelector(`#numerator-${suffix}`).value);
  const denominator = Number(document.querySelector(`#denominator-${suffix}`).value);
  if (!Number.isInteger(numerator) || !Number.isInteger(denominator)) {
    throw new Error("Enter whole numbers for each numerator and denominator.");
  }
  if (denominator === 0) throw new Error("A denominator cannot be zero.");
  return { n: numerator, d: denominator };
}

function calculate(operation) {
  errorMessage.textContent = "";
  decimalValue.textContent = "";
  try {
    const a = readFraction("a");
    const b = readFraction("b");
    let n, d;
    if (operation === "add") { n = a.n * b.d + b.n * a.d; d = a.d * b.d; }
    if (operation === "subtract") { n = a.n * b.d - b.n * a.d; d = a.d * b.d; }
    if (operation === "multiply") { n = a.n * b.n; d = a.d * b.d; }
    if (operation === "divide") {
      if (b.n === 0) throw new Error("Cannot divide by a fraction equal to zero.");
      n = a.n * b.d; d = a.d * b.n;
    }
    if (d < 0) { n = -n; d = -d; }
    const divisor = gcd(n, d);
    n /= divisor;
    d /= divisor;
    resultValue.textContent = `${n}/${d}`;
    decimalValue.textContent = `Decimal: ${(n / d).toFixed(3)}`;
  } catch (error) {
    resultValue.textContent = "Let’s fix that";
    errorMessage.textContent = error.message;
  }
}

calculator.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-operation]");
  if (button) calculate(button.dataset.operation);
});
